/// A call that needs a model engine on this node, answered by the light build
/// (built without the `inference` feature), which has none.
#[cfg(not(feature = "inference"))]
pub(crate) fn engine_absent(method: &str) -> JsonRpcError {
    JsonRpcError {
        code: -32004,
        message: format!(
            "{method} needs a model on this node, and this is the light build of tenzro-node, \
             which runs none"
        ),
        data: Some(serde_json::json!({ "build": "light" })),
    }
}

/// A modality call no provider on the network offers, answered by the light
/// build, which cannot serve it itself.
#[cfg(not(feature = "inference"))]
pub(crate) fn not_offered(method: &str) -> JsonRpcError {
    JsonRpcError {
        code: -32004,
        message: format!(
            "{method}: no provider on the network offers this model, and this is the light build \
             of tenzro-node, which serves no models itself"
        ),
        data: Some(serde_json::json!({ "build": "light" })),
    }
}

/// The part of a modality call this node would serve on its own runtime, in
/// the light build: it has none, so the call is refused. A call for a model a
/// provider on the network serves has already been forwarded to it.
#[cfg(not(feature = "inference"))]
macro_rules! served_by_providers_only {
    ($($local:ident => $method:literal),* $(,)?) => {
        $(
            async fn $local(
                _node: &Arc<TenzroNode>,
                _p: Value,
            ) -> std::result::Result<Value, JsonRpcError> {
                Err(not_offered($method))
            }
        )*
    };
}

#[cfg(not(feature = "inference"))]
served_by_providers_only! {
    forecast_here => "tenzro_forecast",
    image_embed_here => "tenzro_imageEmbed",
    text_embed_here => "tenzro_textEmbed",
    segment_here => "tenzro_segment",
    text_segment_here => "tenzro_textSegment",
    detect_here => "tenzro_detect",
    transcribe_here => "tenzro_transcribe",
    video_embed_here => "tenzro_videoEmbed",
}

/// `tenzro_forecast`: run a forecast on a registered model.
///
/// Params: `{ model_id, history: [f32, ...], horizon: usize,
///            quantiles?: [f32, ...], frequency_seconds?: u64 }`
async fn handle_forecast(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    if let Some(model_id) = p.get("model_id").and_then(Value::as_str)
        && let Some(answer) =
            crate::task_route::forward(node, "tenzro_forecast", "forecast", &p, model_id).await?
    {
        return Ok(answer);
    }
    forecast_here(node, p).await
}

/// `tenzro_forecast` on this node's own runtime.
#[cfg(feature = "inference")]
async fn forecast_here(
    node: &Arc<TenzroNode>,
    p: Value,
) -> std::result::Result<Value, JsonRpcError> {
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let level = crate::verifiable_inference::task_level(node, &p, model_id)?;
    let history: Vec<f32> = p
        .get("history")
        .and_then(|v| v.as_array())
        .ok_or_else(|| missing_param("history"))?
        .iter()
        .filter_map(|v| v.as_f64().map(|f| f as f32))
        .collect();
    if history.is_empty() {
        return Err(JsonRpcError {
            code: -32602,
            message: "'history' must be a non-empty array of numbers".to_string(),
            data: None,
        });
    }
    let horizon = p
        .get("horizon")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| missing_param("horizon"))? as usize;
    let quantiles: Vec<f32> = p
        .get("quantiles")
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_f64().map(|f| f as f32))
                .collect()
        })
        .unwrap_or_default();
    let frequency_seconds = p.get("frequency_seconds").and_then(|v| v.as_u64());

    let cfg = ForecastConfig {
        horizon,
        quantiles,
        frequency_seconds,
    };

    let history_len = history.len();
    let result = node
        .timeseries_runtime
        .forecast(model_id, history, cfg)
        .await
        .map_err(forecast_err)?;

    // A forecast bills per point emitted: one target series times the horizon
    // steps answered. The quantile levels at a step ride on that point, and the
    // context the model read is not charged, so a caller pays for the forecast
    // asked for rather than for the history supplied or the bands requested.
    let points = result.point.len();
    let units = tenzro_types::model::BillableUnits::default()
        .with_forecast_points(points.min(u32::MAX as usize) as u32);
    let emitted = points.saturating_add(result.quantiles.iter().map(|q| q.len()).sum::<usize>());
    let bytes_in = (history_len * std::mem::size_of::<f32>()) as u64;
    let bytes_out = (emitted * std::mem::size_of::<f32>()) as u64;
    let latency_ms = result.generation_time_ms;
    let (cost_wei, settlement) = bill_local_units(
        node,
        &p,
        model_id,
        units.clone(),
        bytes_in,
        bytes_out,
        latency_ms,
    )
    .await?;

    let mut out = serde_json::to_value(result).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("forecast result serialization: {}", e),
        data: None,
    })?;
    crate::verifiable_inference::attach_task_receipt(
        node,
        &p,
        model_id,
        "forecast",
        level,
        units.clone(),
        &mut out,
    )
    .await?;
    if let Some(obj) = out.as_object_mut() {
        obj.insert("units".to_string(), units_to_json(&units));
        obj.insert("cost_wei".to_string(), Value::String(cost_wei.to_string()));
        obj.insert("settlement".to_string(), settlement.to_json());
    }
    Ok(out)
}

/// Resolve a normalization key (`"clip"`/`"imagenet"`/`"siglip"`) into
/// the runtime's strongly-typed normalization. Unknown keys default to CLIP.
#[cfg(feature = "inference")]
fn parse_normalization(key: Option<&str>) -> ImageNormalization {
    match key.unwrap_or("clip").to_lowercase().as_str() {
        "imagenet" => ImageNormalization::IMAGENET,
        "siglip" => ImageNormalization::SIGLIP,
        _ => ImageNormalization::CLIP,
    }
}

/// `tenzro_loadVisionModel`: load a catalog image encoder (CLIP, SigLIP,
/// DINO).
///
/// Params: `{ model_id, visibility? }`. The ONNX graph, input size, embedding
/// dimension and normalization all come from the catalog entry, and its
/// licence tier is enforced.
#[cfg(feature = "inference")]
async fn handle_load_vision_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = catalog_load_params(&p)?;
    let entry =
        get_vision_model_by_id(&model_id).ok_or_else(|| not_in_catalog("vision", &model_id))?;
    let (bundle_dir, provenance) = fetch_catalog_bundle(
        node,
        &model_id,
        &entry.hf_repo,
        vec![entry.hf_filename.clone()],
        entry.size_bytes,
    )
    .await?;

    node.vision_runtime
        .load_onnx(
            model_id.clone(),
            bundle_dir.join(&entry.hf_filename),
            entry.input_size,
            entry.embedding_dim,
            parse_normalization(Some(&entry.normalization)),
        )
        .map_err(forecast_err)?;

    record_multimodal_visibility(node, "tenzro_loadVisionModel", &p, &model_id)?;
    Ok(serde_json::json!({
        "model_id": model_id,
        "bundle_dir": bundle_dir.display().to_string(),
        "loaded": true,
        "provenance": provenance.to_json(),
        "input_size": entry.input_size,
        "embedding_dim": entry.embedding_dim,
    }))
}

