/// `tenzro_loadTextEmbeddingModel`: load a catalog embedder.
///
/// Params: `{ model_id, visibility? }`. The node fetches the files the catalog
/// entry names onto the persistent `effective_models_dir`, verifies them, and
/// registers the embedder on its engine: an ONNX text encoder (graph, its
/// external-data sidecars and the tokenizer), or a pooled embedder in GGUF
/// form on the Praecise engine (the model and, for a vision-language
/// embedder, its projector). Pooling, dimensions and the instruction template
/// come from the catalog entry.
#[cfg(feature = "inference")]
async fn handle_load_text_embedding_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = catalog_load_params(&p)?;
    let result = if let Some(entry) = get_embed_model_by_id(&model_id) {
        download_and_load_praecise_embedder(node, entry).await?
    } else {
        let entry = get_text_embedding_model_by_id(&model_id)
            .ok_or_else(|| not_in_catalog("text-embedding", &model_id))?;
        download_and_load_text_embedding(node, entry).await?
    };
    record_multimodal_visibility(node, "tenzro_loadTextEmbeddingModel", &p, &model_id)?;
    Ok(result)
}

/// Constructs an [`HfArtifactDownloader`] at `models_dir`, wiring the node's
/// iroh resolver as a [`BlobFetcher`] when one is bound so any `PeerHint` on
/// the spec is tried over `tenzro://` before the HF CDN. Without a bound
/// resolver the downloader is HF-only.
pub(crate) fn artifact_downloader(
    node: &Arc<TenzroNode>,
    models_dir: std::path::PathBuf,
) -> HfArtifactDownloader {
    let downloader = HfArtifactDownloader::new(models_dir)
        .with_accepted_licences(node.config().model_licensing.accepted_license_ids.clone());
    match node.iroh_resolver() {
        Some(resolver) => downloader.with_blob_fetcher(
            crate::model_blob_fetcher_bridge::IrohBlobFetcher::arc(resolver.clone()),
        ),
        None => downloader,
    }
}

/// Binds a load that matched verified manifests into a TEE attestation on
/// nodes with real enclave hardware. The report's `user_data` commits to
/// `SHA-256("tenzro/model/verify" || model_id || root_1 || ... || root_n)` over
/// the manifest roots the files matched, packed for the vendor — a
/// hardware-rooted proof that this enclave measured these weights and found
/// them equal to those manifests. Best-effort: a node without TEE, or an
/// attestation failure, does not block a load whose synchronous fail-closed
/// gate already passed. Returns the attested `user_data` hex when a report was
/// produced.
async fn attest_verified_load(
    node: &Arc<TenzroNode>,
    model_id: &str,
    provenance: &crate::trust_hooks::LoadProvenance,
) -> Option<String> {
    let crate::trust_hooks::LoadProvenance::Verified(roots) = provenance else {
        return None;
    };
    let provider = node.tee_provider()?;
    use sha2::{Digest, Sha256};
    let mut h = Sha256::new();
    h.update(b"tenzro/model/verify");
    h.update(model_id.as_bytes());
    for root in roots {
        h.update(hex::decode(root).unwrap_or_default());
    }
    let binding = h.finalize();
    let user_data =
        tenzro_types::tee::pack_user_data_for_vendor(provider.vendor(), binding.as_slice());
    match provider.generate_attestation(&user_data).await {
        Ok(report) => {
            let attested = hex::encode(&report.user_data);
            info!(
                "TEE-attested verify-before-load for {} (vendor {:?}, manifests {}, user_data {})",
                model_id,
                report.vendor,
                roots.join(","),
                attested,
            );
            Some(attested)
        }
        Err(e) => {
            warn!(
                "TEE-attested compare for {} unavailable ({}); \
                 synchronous manifest gate already passed, load proceeds",
                model_id, e,
            );
            None
        }
    }
}

/// The parameters every model load takes: the catalog `model_id`, and an
/// optional `visibility` override.
///
/// Anything else is refused. The files, their repository and every shape
/// decision come from the signed catalog entry, so a caller-supplied path or
/// dimension would be a second way to load the same model.
pub(crate) fn catalog_load_params(p: &Value) -> std::result::Result<String, JsonRpcError> {
    let obj = p.as_object().ok_or_else(|| missing_param("model_id"))?;
    if let Some(extra) = obj
        .keys()
        .find(|k| !matches!(k.as_str(), "model_id" | "visibility"))
    {
        return Err(JsonRpcError {
            code: -32602,
            message: format!(
                "unexpected parameter '{extra}': a model loads by its catalog model_id and an optional visibility"
            ),
            data: None,
        });
    }
    obj.get("model_id")
        .and_then(|v| v.as_str())
        .map(str::to_string)
        .ok_or_else(|| missing_param("model_id"))
}

/// The refusal for a `model_id` the catalog does not list under `kind`.
pub(crate) fn not_in_catalog(kind: &str, model_id: &str) -> JsonRpcError {
    JsonRpcError {
        code: -32602,
        message: format!("'{model_id}' is not a {kind} model in the catalog"),
        data: None,
    }
}

/// Fetch a catalog model's files into its bundle directory and verify them.
///
/// The one path every ONNX loader takes: the licence gate, the fetch (peers
/// first, then the source), the verify-before-load gate against the published
/// manifests, and the attestation. Returns the bundle directory the files
/// landed in and the provenance the gate established.
pub(crate) async fn fetch_catalog_bundle(
    node: &Arc<TenzroNode>,
    model_id: &str,
    hf_repo: &str,
    files: Vec<String>,
    size_bytes: u64,
) -> std::result::Result<(std::path::PathBuf, crate::trust_hooks::LoadProvenance), JsonRpcError> {
    node.check_model_license(model_id)
        .map_err(|m| JsonRpcError {
            code: -32010,
            message: m,
            data: None,
        })?;
    // Weights land on the persistent data_dir volume so they survive a restart.
    let models_dir = node.config().effective_models_dir();
    std::fs::create_dir_all(&models_dir).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("failed to create models dir: {e}"),
        data: None,
    })?;
    let peer_hints = crate::trust_hooks::peer_hints(node, hf_repo, &files);
    let spec = ArtifactSpec::Bundle {
        files: files.clone(),
        dir_name: format!("{model_id}-bundle"),
        peer_hints,
    };
    let (tx, _rx) = tokio::sync::watch::channel(DownloadProgress {
        model_id: model_id.to_string(),
        status: DownloadState::Pending,
        progress_percent: 0.0,
        downloaded_bytes: 0,
        total_bytes: size_bytes,
    });
    let bundle_dir = artifact_downloader(node, models_dir)
        .download(
            model_id,
            hf_repo,
            &spec,
            tenzro_model::SourcePolicy::Auto,
            tx,
        )
        .await
        .map_err(forecast_err)?;
    let provenance = crate::trust_hooks::verify_before_load(
        node,
        hf_repo,
        files
            .iter()
            .map(|f| (f.clone(), bundle_dir.join(f)))
            .collect(),
    )
    .await?;
    attest_verified_load(node, model_id, &provenance).await;
    Ok((bundle_dir, provenance))
}

/// Fetch (or reuse cached) a catalog ONNX text encoder from HuggingFace Hub and
/// register it. When the export ships an external-data sidecar
/// (`model.onnx_data`) the graph, sidecar, and tokenizer are pulled as a
/// co-located bundle so ORT resolves the relative `external_data` reference;
/// self-contained exports pull graph + tokenizer as two single files into the
/// same bundle directory.
#[cfg(feature = "inference")]
async fn download_and_load_text_embedding(
    node: &Arc<TenzroNode>,
    entry: OnnxTextEmbeddingEntry,
) -> std::result::Result<Value, JsonRpcError> {
    let model_id = entry.id.clone();
    let family = text_encoder_family_for_catalog(&entry.family)?;

    let mut files = vec![entry.hf_filename.clone()];
    files.extend(entry.external_data_filenames.iter().cloned());
    files.push(entry.tokenizer_filename.clone());
    let (bundle_dir, provenance) =
        fetch_catalog_bundle(node, &model_id, &entry.hf_repo, files, entry.size_bytes).await?;

    let onnx_path = bundle_dir.join(&entry.hf_filename).display().to_string();
    let tokenizer_path = bundle_dir
        .join(&entry.tokenizer_filename)
        .display()
        .to_string();
    let embedding_dim = entry.embedding_dim as usize;
    let max_sequence_length = entry.max_sequence_length as usize;

    node.text_embedding_runtime
        .load_onnx(
            model_id.clone(),
            onnx_path,
            tokenizer_path,
            family,
            entry.embedding_template.clone(),
            embedding_dim,
            max_sequence_length,
        )
        .map_err(forecast_err)?;

    Ok(serde_json::json!({
        "model_id": model_id,
        "bundle_dir": bundle_dir.display().to_string(),
        "loaded": true,
        "provenance": provenance.to_json(),
        "embedding_dim": embedding_dim,
        "max_sequence_length": max_sequence_length,
        "inputs": ["text"],
    }))
}

/// Fetch a catalog pooled embedder (the GGUF model and, for a
/// vision-language embedder, its projector) and load it on the Praecise
/// engine.
#[cfg(feature = "inference")]
async fn download_and_load_praecise_embedder(
    node: &Arc<TenzroNode>,
    entry: tenzro_model::EmbedModelEntry,
) -> std::result::Result<Value, JsonRpcError> {
    let model_id = entry.id.clone();
    let mut files = vec![entry.hf_filename.clone()];
    files.extend(entry.mmproj.iter().map(|m| m.filename.clone()));
    let (bundle_dir, provenance) =
        fetch_catalog_bundle(node, &model_id, &entry.hf_repo, files, entry.size_bytes).await?;
    // A vision-language embedder serves with its projector and the
    // checkpoint's picture sizing; the catalog carries both or neither.
    let projector = match (&entry.mmproj, &entry.vision_input) {
        (Some(m), Some(input)) => Some((bundle_dir.join(&m.filename), input.clone())),
        (None, None) => None,
        _ => {
            return Err(JsonRpcError {
                code: -32603,
                message: format!(
                    "{model_id}: the catalog entry carries a projector without its picture sizing, or the reverse"
                ),
                data: None,
            });
        }
    };
    let vision = projector.is_some();
    let gguf = bundle_dir.join(&entry.hf_filename);
    let rt = node.text_embedding_runtime.clone();
    let (id, template) = (model_id.clone(), entry.embedding_template.clone());
    let (embedding_dim, max_sequence_length) = (
        entry.embedding_dim as usize,
        entry.max_sequence_length as usize,
    );
    tokio::task::spawn_blocking(move || {
        let projector = projector
            .as_ref()
            .map(|(path, input)| tenzro_model::projector::ProjectorFile { path, input });
        rt.load_praecise(
            &id,
            &gguf,
            projector,
            template,
            embedding_dim,
            max_sequence_length,
        )
    })
    .await
    .map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("embedder load task: {e}"),
        data: None,
    })?
    .map_err(forecast_err)?;
    Ok(serde_json::json!({
        "model_id": model_id,
        "bundle_dir": bundle_dir.display().to_string(),
        "loaded": true,
        "provenance": provenance.to_json(),
        "embedding_dim": embedding_dim,
        "max_sequence_length": max_sequence_length,
        "inputs": if vision { serde_json::json!(["text", "image", "video"]) } else { serde_json::json!(["text"]) },
    }))
}

/// Map a catalog model-name family (`OnnxTextEmbeddingEntry::family`) to the
/// runtime pooling kind. Qwen3-Embedding pools the last token; BGE-M3 and
/// Snowflake Arctic pool the CLS token; ModernBERT-embed mean-pools;
/// EmbeddingGemma's and Harrier's exports ship a pre-pooled `sentence_embedding`.
#[cfg(feature = "inference")]
fn text_encoder_family_for_catalog(
    family: &str,
) -> std::result::Result<TextEncoderFamily, JsonRpcError> {
    match family
        .to_ascii_lowercase()
        .replace(['-', ' '], "_")
        .as_str()
    {
        "qwen3_embedding" => Ok(TextEncoderFamily::Qwen3),
        "bge" | "bge_m3" | "arctic" | "snowflake" => Ok(TextEncoderFamily::Cls),
        "modernbert" => Ok(TextEncoderFamily::Mean),
        "embeddinggemma" | "harrier" | "nemotron_embed" | "qwen3_vl_embedding" => {
            Ok(TextEncoderFamily::SentenceEmbedding)
        }
        other => Err(JsonRpcError {
            code: -32602,
            message: format!("catalog family '{other}' has no known pooling kind"),
            data: None,
        }),
    }
}

/// EdgeSAM and MobileSAM are SAM-1-architecture distillations, so they share
/// the 6-input decoder ABI. Accepting their catalog `family` strings here lets
/// a caller pass the catalog value through verbatim.
#[cfg(feature = "inference")]
fn parse_sam_family(s: &str) -> std::result::Result<SamFamily, JsonRpcError> {
    match s.to_ascii_lowercase().replace(['-', ' '], "_").as_str() {
        "sam1" | "sam" | "edgesam" | "mobilesam" => Ok(SamFamily::Sam1),
        "sam2" => Ok(SamFamily::Sam2),
        other => Err(JsonRpcError {
            code: -32602,
            message: format!("unknown SAM family '{other}' (sam1|sam2|edgesam|mobilesam)"),
            data: None,
        }),
    }
}

#[cfg(feature = "inference")]
fn parse_detr_family(s: &str) -> std::result::Result<DetrFamily, JsonRpcError> {
    match s.to_ascii_lowercase().replace(['-', ' '], "_").as_str() {
        "rf_detr" | "rfdetr" => Ok(DetrFamily::RfDetr),
        "d_fine" | "dfine" => Ok(DetrFamily::DFine),
        other => Err(JsonRpcError {
            code: -32602,
            message: format!("unknown DETR family '{other}' (rf_detr|d_fine)"),
            data: None,
        }),
    }
}

/// `tenzro_unloadTextEmbeddingModel`: drop a registered text encoder.
#[cfg(feature = "inference")]
async fn handle_unload_text_embedding_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let removed = node.text_embedding_runtime.unregister(model_id);
    forget_multimodal_model(node, model_id);
    Ok(serde_json::json!({ "model_id": model_id, "removed": removed }))
}

/// `tenzro_listTextEmbeddingCatalog`: the catalog's embedders, each with the
/// engine it runs on (`onnx-text-embedding`, or `embed` for a pooled embedder
/// on the Praecise engine).
async fn handle_list_text_embedding_catalog() -> std::result::Result<Value, JsonRpcError> {
    fn tag(engine: &str, mut rows: Vec<Value>) -> Vec<Value> {
        for row in &mut rows {
            if let Some(obj) = row.as_object_mut() {
                obj.insert("engine".into(), serde_json::json!(engine));
            }
        }
        rows
    }
    let mut models = tag(
        "onnx-text-embedding",
        crate::catalog_rpc::with_licence(&get_text_embedding_catalog()),
    );
    models.extend(tag(
        "embed",
        crate::catalog_rpc::with_licence(&get_embed_catalog()),
    ));
    Ok(serde_json::json!({ "models": models }))
}

/// `tenzro_textEmbed`: embed inputs with a registered encoder.
///
/// Params: `{ model_id, inputs: [Input,...], requested_dim?: u32,
/// normalize?: bool, role?: { "role": "document", "title"?: String } |
/// { "role": "query", "task"?: String } }`. `role` drives the per-family
/// instruction template (see [`tenzro_model::EmbeddingTemplate`]) —
/// defaults to `document` when omitted. An `Input` is a string (text) or
/// `{ text?: String, image?: base64, video?: [base64 frame, ...] }`, embedded
/// as one item; pictures and video need a vision-language embedder. Visual
/// tokens are input tokens, billed like text.
pub(crate) async fn handle_text_embed(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    if let Some(model_id) = p.get("model_id").and_then(Value::as_str)
        && let Some(answer) =
            crate::task_route::forward(node, "tenzro_textEmbed", "text_embed", &p, model_id).await?
    {
        return Ok(answer);
    }
    if let Some(upstream) = p
        .get("model_id")
        .and_then(Value::as_str)
        .and_then(|m| node.upstream_model(m))
        .cloned()
    {
        return crate::connector::serve_text_embed(node, &upstream, p).await;
    }
    text_embed_here(node, p).await
}

/// `tenzro_textEmbed` on this node's own runtime.
#[cfg(feature = "inference")]
async fn text_embed_here(
    node: &Arc<TenzroNode>,
    p: Value,
) -> std::result::Result<Value, JsonRpcError> {
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let level = crate::verifiable_inference::task_level(node, &p, model_id)?;
    let inputs: Vec<tenzro_model::EmbedInput> = serde_json::from_value(
        p.get("inputs")
            .cloned()
            .ok_or_else(|| missing_param("inputs"))?,
    )
    .map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("'inputs': {e}"),
        data: None,
    })?;
    if inputs.is_empty() {
        return Err(JsonRpcError {
            code: -32602,
            message: "'inputs' must be a non-empty array".to_string(),
            data: None,
        });
    }
    let requested_dim = p
        .get("requested_dim")
        .and_then(|v| v.as_u64())
        .map(|n| n as u32);
    let normalize = p
        .get("normalize")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    // `role` distinguishes query vs. document for families whose template
    // needs it (see `EmbeddingTemplate`) — defaults to Document, same
    // reasoning as `EmbedRole::default()`. Malformed input falls back to
    // the default rather than erroring: a caller that got the shape wrong
    // still gets a same-or-slightly-lower-quality embedding, not a refusal.
    let role = p
        .get("role")
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .unwrap_or_default();
    let cfg = TextEmbedConfig {
        requested_dim,
        normalize,
        role,
    };
    let bytes_in = inputs.iter().map(|i| i.byte_len()).sum();
    let result = node
        .text_embedding_runtime
        .embed(model_id, inputs, cfg)
        .await
        .map_err(forecast_err)?;

    // An encoder produces no completion, so the whole charge falls on the
    // prompt side — counted from the attention mask so batch padding is not
    // billed as caller work.
    let units = tenzro_types::model::BillableUnits::tokens(result.prompt_tokens, 0);
    let bytes_out = (result.embeddings.iter().map(|e| e.len()).sum::<usize>()
        * std::mem::size_of::<f32>()) as u64;
    let latency_ms = result.generation_time_ms;
    let (cost_wei, settlement) = bill_local_units(
        node,
        &p,
        model_id,
        units.clone(),
        bytes_in,
        bytes_out,
        latency_ms,
    )
    .await?;

    let mut out = serde_json::to_value(result).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("text-embed serialization: {}", e),
        data: None,
    })?;
    crate::verifiable_inference::attach_task_receipt(
        node,
        &p,
        model_id,
        "text_embed",
        level,
        units.clone(),
        &mut out,
    )
    .await?;
    if let Some(obj) = out.as_object_mut() {
        obj.insert("units".to_string(), units_to_json(&units));
        obj.insert("cost_wei".to_string(), Value::String(cost_wei.to_string()));
        obj.insert("settlement".to_string(), settlement.to_json());
    }
    Ok(out)
}

