/// `tenzro_loadSegmentationModel`: load a catalog point/box-prompted
/// segmenter (SAM 2, EdgeSAM, MobileSAM).
///
/// Params: `{ model_id, visibility? }`. The encoder and decoder graphs, family
/// and input resolution come from the catalog entry, and its licence tier is
/// enforced. The ONNX session loads only with `--features onnx` (else "ONNX
/// backend not enabled").
#[cfg(feature = "inference")]
async fn handle_load_segmentation_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = catalog_load_params(&p)?;
    let entry = get_segmentation_model_by_id(&model_id)
        .ok_or_else(|| not_in_catalog("segmentation", &model_id))?;
    let family = parse_sam_family(&entry.family)?;
    let (bundle_dir, provenance) = fetch_catalog_bundle(
        node,
        &model_id,
        &entry.hf_repo,
        vec![
            entry.encoder_filename.clone(),
            entry.decoder_filename.clone(),
        ],
        entry.size_bytes,
    )
    .await?;
    node.segmentation_runtime
        .load_onnx(
            model_id.clone(),
            bundle_dir.join(&entry.encoder_filename),
            bundle_dir.join(&entry.decoder_filename),
            family,
            entry.input_size,
        )
        .map_err(forecast_err)?;
    record_multimodal_visibility(node, "tenzro_loadSegmentationModel", &p, &model_id)?;
    Ok(serde_json::json!({
        "model_id": model_id,
        "bundle_dir": bundle_dir.display().to_string(),
        "loaded": true,
        "provenance": provenance.to_json(),
        "input_size": entry.input_size,
    }))
}

