/// `tenzro_textSegment`: open-vocabulary text-promptable segmentation.
///
/// Params: `{ model_id, image_base64: String, text_prompt: String,
///            box_prompt?: TextSegmentBoxPrompt, score_threshold?: f32 }`
pub(crate) async fn handle_text_segment(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    if let Some(model_id) = p.get("model_id").and_then(Value::as_str)
        && let Some(answer) =
            crate::task_route::forward(node, "tenzro_textSegment", "text_segment", &p, model_id)
                .await?
    {
        return Ok(answer);
    }
    text_segment_here(node, p).await
}

/// `tenzro_textSegment` on this node's own runtime.
#[cfg(feature = "inference")]
async fn text_segment_here(
    node: &Arc<TenzroNode>,
    p: Value,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let level = crate::verifiable_inference::task_level(node, &p, model_id)?;
    let b64 = p
        .get("image_base64")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("image_base64"))?;
    let text_prompt = p
        .get("text_prompt")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("text_prompt"))?
        .to_string();
    let box_prompt: Option<TextSegmentBoxPrompt> = match p.get("box_prompt") {
        Some(v) if !v.is_null() => {
            Some(serde_json::from_value(v.clone()).map_err(|e| JsonRpcError {
                code: -32602,
                message: format!("invalid 'box_prompt': {}", e),
                data: None,
            })?)
        }
        _ => None,
    };
    let score_threshold = p
        .get("score_threshold")
        .and_then(|v| v.as_f64())
        .map(|f| f as f32)
        .unwrap_or(0.5);

    let bytes = base64::engine::general_purpose::STANDARD
        .decode(b64)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid base64 in 'image_base64': {}", e),
            data: None,
        })?;
    let prompt_len = text_prompt.len();
    let config = TextSegmentConfig {
        text_prompt,
        box_prompt,
        score_threshold,
    };
    let bytes_in = bytes.len() as u64 + prompt_len as u64;
    let geometry = tenzro_model::image_dimensions(&bytes);
    let result = node
        .text_segmentation_runtime
        .segment_with_text(model_id, bytes, config)
        .await
        .map_err(forecast_err)?;

    // Three passes run here: the image encoder over the geometry, the language
    // encoder over the phrase, and the decoder once per detection returned. The
    // language pass pads to the tokenizer's fixed length, so its cost does not
    // vary with the phrase and the per-request floor already covers it — only
    // the geometry and the detection count are charged as units.
    let image_tokens = geometry
        .map(|(w, h)| image_tokenization_for(node, model_id).image_tokens(w, h))
        .unwrap_or(0);
    let units = tenzro_types::model::BillableUnits::tokens(
        0,
        result.segmentations.len().min(u32::MAX as usize) as u32,
    )
    .with_image_tokens(image_tokens);
    let bytes_out = result
        .segmentations
        .iter()
        .map(|s| s.mask.len() as u64)
        .sum();
    let latency_ms = result.generation_time_ms;
    let (cost_wei, settlement) = bill_local_units(
        node,
        &p,
        model_id,
        units.clone(),
        bytes_in,
        bytes_out,
        latency_ms,
    )
    .await?;

    let mut out = serde_json::to_value(result).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("text-segment result serialization: {}", e),
        data: None,
    })?;
    crate::verifiable_inference::attach_task_receipt(
        node,
        &p,
        model_id,
        "text_segment",
        level,
        units.clone(),
        &mut out,
    )
    .await?;
    if let Some(obj) = out.as_object_mut() {
        obj.insert("units".to_string(), units_to_json(&units));
        obj.insert("cost_wei".to_string(), Value::String(cost_wei.to_string()));
        obj.insert("settlement".to_string(), settlement.to_json());
    }
    Ok(out)
}

// ============================================================================
// Object detection — RF-DETR, D-FINE
// ============================================================================

/// `tenzro_loadDetectionModel`: load a catalog object detector (RF-DETR,
/// D-FINE).
///
/// Params: `{ model_id, visibility? }`. The ONNX graph, family, input
/// resolution and class count come from the catalog entry, and its licence
/// tier is enforced. The ONNX session loads only with `--features onnx` (else
/// "ONNX backend not enabled").
#[cfg(feature = "inference")]
async fn handle_load_detection_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = catalog_load_params(&p)?;
    let entry = get_detection_model_by_id(&model_id)
        .ok_or_else(|| not_in_catalog("detection", &model_id))?;
    let family = parse_detr_family(&entry.family)?;
    let (bundle_dir, provenance) = fetch_catalog_bundle(
        node,
        &model_id,
        &entry.hf_repo,
        vec![entry.hf_filename.clone()],
        entry.size_bytes,
    )
    .await?;
    node.detection_runtime
        .load_onnx(
            model_id.clone(),
            bundle_dir.join(&entry.hf_filename),
            family,
            entry.input_size,
            entry.num_classes,
        )
        .map_err(forecast_err)?;
    record_multimodal_visibility(node, "tenzro_loadDetectionModel", &p, &model_id)?;
    Ok(serde_json::json!({
        "model_id": model_id,
        "bundle_dir": bundle_dir.display().to_string(),
        "loaded": true,
        "provenance": provenance.to_json(),
        "input_size": entry.input_size,
        "num_classes": entry.num_classes,
    }))
}

