/// `tenzro_detect`: object detection on an image.
///
/// Params: `{ model_id, image_base64: String, score_threshold?: f32 }`
pub(crate) async fn handle_detect(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    if let Some(model_id) = p.get("model_id").and_then(Value::as_str)
        && let Some(answer) =
            crate::task_route::forward(node, "tenzro_detect", "detect", &p, model_id).await?
    {
        return Ok(answer);
    }
    detect_here(node, p).await
}

/// `tenzro_detect` on this node's own runtime.
#[cfg(feature = "inference")]
async fn detect_here(node: &Arc<TenzroNode>, p: Value) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let level = crate::verifiable_inference::task_level(node, &p, model_id)?;
    let b64 = p
        .get("image_base64")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("image_base64"))?;
    let score_threshold = p
        .get("score_threshold")
        .and_then(|v| v.as_f64())
        .map(|f| f as f32)
        .unwrap_or(0.25);
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(b64)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid base64 in 'image_base64': {}", e),
            data: None,
        })?;
    let bytes_in = bytes.len() as u64;
    let geometry = tenzro_model::image_dimensions(&bytes);
    let result = node
        .detection_runtime
        .detect(model_id, bytes, score_threshold)
        .await
        .map_err(forecast_err)?;

    // A DETR runs one encoder pass over the geometry and emits a fixed query
    // set; what varies with the caller's threshold is how many detections
    // survive, so the returned count is the emitted dimension.
    let image_tokens = geometry
        .map(|(w, h)| image_tokenization_for(node, model_id).image_tokens(w, h))
        .unwrap_or(0);
    let units = tenzro_types::model::BillableUnits::tokens(
        0,
        result.detections.len().min(u32::MAX as usize) as u32,
    )
    .with_image_tokens(image_tokens);
    let latency_ms = result.generation_time_ms;

    let mut out = serde_json::to_value(result).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("detect result serialization: {}", e),
        data: None,
    })?;
    let bytes_out = out.to_string().len() as u64;
    let (cost_wei, settlement) = bill_local_units(
        node,
        &p,
        model_id,
        units.clone(),
        bytes_in,
        bytes_out,
        latency_ms,
    )
    .await?;
    crate::verifiable_inference::attach_task_receipt(
        node,
        &p,
        model_id,
        "detect",
        level,
        units.clone(),
        &mut out,
    )
    .await?;
    if let Some(obj) = out.as_object_mut() {
        obj.insert("units".to_string(), units_to_json(&units));
        obj.insert("cost_wei".to_string(), Value::String(cost_wei.to_string()));
        obj.insert("settlement".to_string(), settlement.to_json());
    }
    Ok(out)
}

// ============================================================================
// Audio ASR — Moonshine, Whisper, Parakeet, Canary, Distil-Whisper
// ============================================================================

/// `tenzro_loadAudioModel`: load a catalog speech-recognition model
/// (Moonshine, Whisper, Parakeet, Canary).
///
/// Params: `{ model_id, visibility? }`. The encoder, decoder, tokenizer and
/// (for the NeMo families) the feature-extractor graph come from the catalog
/// entry, as do the family and the longest segment it accepts. The Whisper
/// decoder variant follows from the catalog id. Canary loads as English
/// recognition without translation.
#[cfg(feature = "inference")]
async fn handle_load_audio_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = catalog_load_params(&p)?;
    let entry =
        get_audio_model_by_id(&model_id).ok_or_else(|| not_in_catalog("audio", &model_id))?;
    let unusable = |what: &str| JsonRpcError {
        code: -32602,
        message: format!(
            "catalog entry '{model_id}' ({}) names no {what}",
            entry.family
        ),
        data: None,
    };
    let decoder = entry
        .decoder_filename
        .clone()
        .ok_or_else(|| unusable("decoder"))?;
    let preprocessor = match entry.family.as_str() {
        "parakeet" | "canary" => Some(
            entry
                .preprocessor_filename
                .clone()
                .ok_or_else(|| unusable("preprocessor"))?,
        ),
        _ => None,
    };
    let mut files = vec![
        entry.encoder_filename.clone(),
        decoder.clone(),
        entry.tokenizer_filename.clone(),
    ];
    files.extend(preprocessor.clone());
    let (bundle_dir, provenance) =
        fetch_catalog_bundle(node, &model_id, &entry.hf_repo, files, entry.size_bytes).await?;

    let encoder_path = bundle_dir.join(&entry.encoder_filename);
    let decoder_path = bundle_dir.join(&decoder);
    let tokenizer_path = bundle_dir.join(&entry.tokenizer_filename);
    let max_audio_seconds = entry.max_audio_seconds;
    match (entry.family.as_str(), preprocessor) {
        ("moonshine", _) => node
            .audio_runtime
            .load_moonshine(
                model_id.clone(),
                &encoder_path,
                &decoder_path,
                &tokenizer_path,
                max_audio_seconds,
            )
            .map_err(forecast_err)?,
        ("whisper", _) => {
            let variant = match model_id.as_str() {
                "distil-whisper-small-en" | "distil-whisper-medium-en" => WhisperFamily::DistilEn,
                "distil-whisper-large-v3" => WhisperFamily::DistilLargeV3,
                "whisper-large-v3-turbo" => WhisperFamily::LargeV3Turbo,
                _ => return Err(unusable("known Whisper decoder variant")),
            };
            node.audio_runtime
                .load_whisper(
                    model_id.clone(),
                    &encoder_path,
                    &decoder_path,
                    &tokenizer_path,
                    variant,
                    max_audio_seconds,
                )
                .map_err(forecast_err)?
        }
        ("parakeet", Some(pre)) => node
            .audio_runtime
            .load_parakeet(
                model_id.clone(),
                bundle_dir.join(pre),
                &encoder_path,
                &decoder_path,
                &tokenizer_path,
                max_audio_seconds,
            )
            .map_err(forecast_err)?,
        ("canary", Some(pre)) => node
            .audio_runtime
            .load_canary(
                model_id.clone(),
                bundle_dir.join(pre),
                &encoder_path,
                &decoder_path,
                &tokenizer_path,
                "en".to_string(),
                "en".to_string(),
                max_audio_seconds,
            )
            .map_err(forecast_err)?,
        (other, _) => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "unknown audio family '{other}' (expected: moonshine, whisper, parakeet, canary)"
                ),
                data: None,
            });
        }
    }

    record_multimodal_visibility(node, "tenzro_loadAudioModel", &p, &model_id)?;
    Ok(serde_json::json!({
        "model_id": model_id,
        "bundle_dir": bundle_dir.display().to_string(),
        "loaded": true,
        "provenance": provenance.to_json(),
        "family": entry.family,
        "max_audio_seconds": max_audio_seconds,
    }))
}

