/// `tenzro_transcribe`: ASR on an audio clip.
///
/// Params: `{ model_id, audio_base64: String, language?: String,
///            timestamps?: bool, temperature?: f32 }`
pub(crate) async fn handle_transcribe(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    if let Some(model_id) = p.get("model_id").and_then(Value::as_str)
        && let Some(answer) =
            crate::task_route::forward(node, "tenzro_transcribe", "transcribe", &p, model_id)
                .await?
    {
        return Ok(answer);
    }
    transcribe_here(node, p).await
}

/// `tenzro_transcribe` on this node's own runtime.
#[cfg(feature = "inference")]
async fn transcribe_here(
    node: &Arc<TenzroNode>,
    p: Value,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let level = crate::verifiable_inference::task_level(node, &p, model_id)?;
    let b64 = p
        .get("audio_base64")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("audio_base64"))?;
    let language = p
        .get("language")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());
    let timestamps = p
        .get("timestamps")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let temperature = p
        .get("temperature")
        .and_then(|v| v.as_f64())
        .map(|f| f as f32);
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(b64)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid base64 in 'audio_base64': {}", e),
            data: None,
        })?;
    let cfg = TranscribeConfig {
        language,
        timestamps,
        temperature,
    };
    let bytes_in = bytes.len() as u64;
    let result = node
        .audio_runtime
        .transcribe(model_id, bytes, cfg)
        .await
        .map_err(forecast_err)?;

    // ASR is charged on the audio the encoder actually consumed. The transcript
    // is not counted as output tokens: the runtime returns detokenized text and
    // the decoder step count is not recoverable from it, so a word or character
    // count would be a guess rather than a measurement.
    let units = tenzro_types::model::BillableUnits::default().with_audio_ms(result.audio_ms);
    let bytes_out = result.text.len() as u64;
    let latency_ms = result.generation_time_ms;
    let (cost_wei, settlement) = bill_local_units(
        node,
        &p,
        model_id,
        units.clone(),
        bytes_in,
        bytes_out,
        latency_ms,
    )
    .await?;

    let mut out = serde_json::to_value(result).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("transcribe result serialization: {}", e),
        data: None,
    })?;
    crate::verifiable_inference::attach_task_receipt(
        node,
        &p,
        model_id,
        "transcribe",
        level,
        units.clone(),
        &mut out,
    )
    .await?;
    if let Some(obj) = out.as_object_mut() {
        obj.insert("units".to_string(), units_to_json(&units));
        obj.insert("cost_wei".to_string(), Value::String(cost_wei.to_string()));
        obj.insert("settlement".to_string(), settlement.to_json());
    }
    Ok(out)
}

// ============================================================================
// Video — V-JEPA 2 ViT-L/H/g advertised; loader pending per-model ONNX export
// ============================================================================

/// `tenzro_loadVideoModel`: register a clip encoder built from a loaded image
/// encoder.
///
/// Params: `{ model_id, vision_model_id, num_frames? }`
///
/// The catalog advertises V-JEPA 2 ViT-L / ViT-H / ViT-g, but the upstream
/// facebook/vjepa2-* repos ship safetensors only, so there is no native video
/// graph to load. The frame-pooling path is what the runtime can serve: it
/// borrows an already-loaded image encoder, samples evenly-spaced frames, and
/// mean-pools their embeddings. Load the image tower first via
/// `tenzro_loadVisionModel`, then name it here as `vision_model_id`.
#[cfg(feature = "inference")]
async fn handle_load_video_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let vision_model_id = p
        .get("vision_model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("vision_model_id"))?;
    let num_frames = p
        .get("num_frames")
        .and_then(|v| v.as_u64())
        .unwrap_or(8)
        .clamp(1, 128) as u32;

    tenzro_model::access::check(vision_model_id).map_err(|e| JsonRpcError {
        code: -32001,
        message: e.to_string(),
        data: None,
    })?;
    let encoder = node
        .vision_runtime
        .encoder(vision_model_id)
        .ok_or_else(|| JsonRpcError {
            code: -32004,
            message: format!(
                "image encoder '{}' is not loaded; load it with tenzro_loadVisionModel first",
                vision_model_id
            ),
            data: None,
        })?;

    node.video_runtime
        .register_frame_pooled(model_id, encoder, num_frames)
        .map_err(forecast_err)?;

    record_multimodal_visibility(node, "tenzro_loadVideoModel", &p, model_id)?;
    Ok(serde_json::json!({
        "model_id": model_id,
        "vision_model_id": vision_model_id,
        "num_frames": num_frames,
        "loaded": true,
    }))
}

