#[cfg(test)]
mod did_document_services_tests {
    use super::set_document_services;
    use tenzro_types::did_services::{DidServiceEntry, DidServices};

    /// Two nodes holding the same consensus state return the same DID
    /// document: its `service` list is the one chain state holds, whatever
    /// the node's own registry carried.
    #[test]
    fn two_nodes_return_identical_service_lists() {
        let did = "did:tenzro:human:ab";
        let services = DidServices {
            version: 2,
            services: vec![DidServiceEntry {
                id: "inbox".to_string(),
                service_type: "MessagingService".to_string(),
                endpoint: "https://inbox.example.org/b".to_string(),
            }],
        };
        let mut on_a = serde_json::json!({ "id": did, "service": [{ "id": "local-only" }] });
        let mut on_b = serde_json::json!({ "id": did });
        set_document_services(&mut on_a, did, &services);
        set_document_services(&mut on_b, did, &services);
        assert_eq!(on_a, on_b);
        assert_eq!(on_a["service"][0]["id"], "did:tenzro:human:ab#inbox");
        assert_eq!(
            on_a["service"][0]["serviceEndpoint"],
            "https://inbox.example.org/b"
        );

        set_document_services(&mut on_a, did, &DidServices::default());
        assert!(on_a.get("service").is_none());
    }
}

#[cfg(test)]
mod inference_admission_params_tests {
    use super::*;
    use tenzro_types::Visibility;

    fn request(params: Value) -> JsonRpcRequest {
        serde_json::from_value(serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "tenzro_chat",
            "params": params,
        }))
        .expect("request")
    }

    /// A private model is refused whether its params arrive as an object or
    /// as that object wrapped in an array, which the handler reads alike.
    #[tokio::test]
    async fn array_wrapped_params_meet_the_same_model_admission() {
        let tmp = tempfile::tempdir().expect("temp dir");
        let config = crate::config::NodeConfig {
            data_dir: tmp.path().to_path_buf(),
            models_dir: Some(tmp.path().join("models")),
            // A routable listener: a caller's origin is unknown here.
            rpc_addr: "0.0.0.0:8545".to_string(),
            ..crate::config::NodeConfig::default()
        };
        let mut node = TenzroNode::new(config).await.expect("node");
        node.init_storage().await.expect("storage");
        let node = Arc::new(node);
        record_served_model(&node, "m", Some(Visibility::Private));

        let object = serde_json::json!({ "model_id": "m", "message": "hi" });
        let plain =
            inference_admission_refusal(&node, Surface::Rpc, &request(object.clone()), None)
                .expect("a private model is refused");
        assert_eq!(plain.code, -32001);
        let wrapped = inference_admission_refusal(
            &node,
            Surface::Rpc,
            &request(Value::Array(vec![object])),
            None,
        )
        .expect("the same call wrapped in an array is refused too");
        assert_eq!(wrapped.code, -32001);
        assert_eq!(wrapped.message, plain.message);
    }

    /// A `tenzro_chat` this node forwards is settled by paying the provider
    /// routing picks from the caller's channel voucher, so admission checks
    /// the voucher against that provider, not against this node's payee.
    #[tokio::test]
    async fn a_forwarded_chat_checks_the_voucher_against_the_serving_provider() {
        let tmp = tempfile::tempdir().expect("temp dir");
        let config = crate::config::NodeConfig {
            data_dir: tmp.path().to_path_buf(),
            models_dir: Some(tmp.path().join("models")),
            rpc_addr: "0.0.0.0:8545".to_string(),
            ..crate::config::NodeConfig::default()
        };
        let mut node = TenzroNode::new(config).await.expect("node");
        node.init_storage().await.expect("storage");
        let node = Arc::new(node);
        *node.node_visibility.write() = Visibility::Public;
        let provider = Address::new([0x7a; 32]);
        node.network_models.insert(
            "m".to_string(),
            crate::node::NetworkModelEntry {
                registration: tenzro_network::ModelRegistrationMessage {
                    model_id: "m".to_string(),
                    provider: format!("0x{}", hex::encode(provider.as_bytes())),
                    iroh_endpoint_id: "remote-endpoint".to_string(),
                    ttl_secs: 600,
                    ..Default::default()
                },
                last_seen: std::time::Instant::now(),
            },
        );
        let voucher = tenzro_types::payment_authorization::EscrowVoucher {
            binding: [0u8; 32],
            escrow_id: [0x11; 32],
            cumulative_amount: 1,
            public_key: vec![0x04; 65],
            signature: tenzro_crypto::composite::CompositeSignature::classical(
                tenzro_crypto::composite::ClassicalProof::Raw {
                    signature: vec![0u8; 64],
                },
            ),
            agent: None,
            attribution: None,
        };
        let call = serde_json::json!({
            "model_id": "m",
            "message": "hi",
            "channel_voucher": voucher,
        });

        // This node has no payee of its own; the provider it forwards to does.
        assert_eq!(node.operator_payee(), None);
        assert_eq!(voucher_payee(&node, &request(call.clone())), Ok(provider));
        let refusal = inference_admission_refusal(&node, Surface::Rpc, &request(call), None)
            .expect("this node holds no channels, so the voucher is not honoured");
        assert!(
            refusal.message.contains("holds no payment channels"),
            "the voucher was checked against a payee other than the provider: {}",
            refusal.message
        );
    }
}

#[cfg(all(test, feature = "inference"))]
mod spot_tier_admission_tests {
    use super::*;

    /// The real claim behind wiring a buyer's `spot` choice into
    /// `admit_local_inference_as`: `qos_class(true)` must be the class the
    /// batch reservation actually sheds once full, and `qos_class(false)`
    /// the class it never sheds for this reason. Checked directly against
    /// `TrafficManager`, the way `serving_admission.rs`'s own admission
    /// tests already do (`an_llm_at_capacity_gets_the_same_busy_answer_as_onnx`)
    /// -- a model that never finishes loading in a bare test node never
    /// reaches this layer through the full RPC handler at all, so that path
    /// cannot be exercised end to end without a real engine and weights.
    #[test]
    fn qos_class_of_spot_is_what_the_batch_reservation_actually_sheds() {
        let traffic = tenzro_model::traffic::TrafficManager::default();
        let shape = tenzro_model::traffic::Shape::new(1, 1);

        let mut held = Vec::new();
        loop {
            match traffic.admit("m", qos_class(true), None, shape) {
                Ok(guard) => held.push(guard),
                Err(_) => break,
            }
            assert!(held.len() < 10_000, "batch reservation never saturated");
        }
        assert!(!held.is_empty(), "the default batch reservation is zero");

        let refusal = traffic
            .admit("m", qos_class(true), None, shape)
            .expect_err("spot work is shed once the batch reservation is full");
        assert!(
            matches!(
                refusal,
                tenzro_model::traffic::Refusal::ShedForInteractive { .. }
            ),
            "refused for the wrong reason: {refusal:?}"
        );

        traffic
            .admit("m", qos_class(false), None, shape)
            .expect("an ordinary (interactive) request is never shed for this reason");
    }

    /// `spot_requested`/`qos_class` parse and classify consistently with
    /// what the handlers above actually send through `admit_local_inference_as`.
    #[test]
    fn spot_is_off_by_default_so_an_old_caller_sees_no_change() {
        assert_eq!(
            qos_class(spot_requested(
                &serde_json::json!({"model_id": "m", "message": "hi"})
            )),
            tenzro_model::traffic::QosClass::Interactive
        );
    }
}

#[cfg(all(test, feature = "inference"))]
mod stop_and_serve_tests {
    use super::*;

    const MODEL: &str = "qwen3-4b";

    async fn node_with_runtime(tmp: &std::path::Path) -> Arc<TenzroNode> {
        let config = crate::config::NodeConfig {
            data_dir: tmp.to_path_buf(),
            models_dir: Some(tmp.join("models")),
            ..crate::config::NodeConfig::default()
        };
        let mut node = TenzroNode::new(config).await.expect("node");
        node.init_storage().await.expect("storage");
        node.model_runtime = Some(Arc::new(
            tenzro_model::ModelRuntime::new().expect("runtime"),
        ));
        Arc::new(node)
    }

    fn served_record(node: &TenzroNode, model_id: &str) -> bool {
        node.storage()
            .and_then(|s| {
                s.get(CF_MODELS, format!("served:{model_id}").as_bytes())
                    .ok()
                    .flatten()
            })
            .is_some()
    }

    /// A served model whose first request is still loading it is stopped, not
    /// refused as "not loaded": the refusal left the load free to install the
    /// weights of a model the operator had just stopped.
    #[tokio::test]
    async fn a_stop_while_the_first_request_loads_the_model_holds() {
        let tmp = tempfile::tempdir().expect("temp dir");
        let node = node_with_runtime(tmp.path()).await;
        let runtime = node.model_runtime.clone().unwrap();
        record_served_model(&node, MODEL, None);
        assert!(
            !runtime.is_loaded(MODEL),
            "lazily served: weights not resident yet"
        );

        let stopped = handle_stop_model(&node, Some(serde_json::json!({ "model_id": MODEL })))
            .await
            .expect("a served model is stopped even while it loads");
        assert_eq!(stopped["status"], "stopped");

        assert!(
            runtime.is_stopped(MODEL),
            "loads must be refused after the stop"
        );
        assert!(node.is_offloaded(MODEL));
        assert!(!node.served_models.contains_key(MODEL));
        assert!(!served_record(&node, MODEL));
        assert_eq!(node.ensure_local_model_loaded(MODEL).await, Ok(false));
        assert!(!runtime.is_loaded(MODEL));
    }

    /// Serve after stop restores the whole serving state, and again changes
    /// nothing: one service instance, the served record, the tracker, the
    /// cleared marker, and a runtime that loads the model again.
    #[tokio::test]
    async fn serve_after_stop_registers_the_model_again() {
        let tmp = tempfile::tempdir().expect("temp dir");
        let node = node_with_runtime(tmp.path()).await;
        let runtime = node.model_runtime.clone().unwrap();
        let entry = tenzro_model::HfModelEntry {
            id: MODEL.to_string(),
            name: "Qwen3 4B".to_string(),
            parameters: "4B".to_string(),
            ..Default::default()
        };
        record_served_model(&node, MODEL, None);
        handle_stop_model(&node, Some(serde_json::json!({ "model_id": MODEL })))
            .await
            .expect("stop");

        let first = restore_serving_state(&node, MODEL, &entry, None, None).await;
        let second = restore_serving_state(&node, MODEL, &entry, None, None).await;

        assert_eq!(first, second, "a repeated serve reuses the one instance");
        let service = node
            .get_model_service(&first)
            .expect("service registered again");
        assert_eq!(service.model_id, MODEL);
        let instances = node
            .model_services
            .iter()
            .filter(|s| s.value().model_id == MODEL)
            .count();
        assert_eq!(instances, 1);
        assert!(node.served_models.contains_key(MODEL));
        assert!(served_record(&node, MODEL));
        assert!(!node.is_offloaded(MODEL));
        assert!(node.load_tracker.snapshot(MODEL).is_some());
        assert!(!runtime.is_stopped(MODEL));
    }
}

#[cfg(test)]
mod slow_request_real_path_tests {
    use super::*;

    /// A fast method through the real `handle_request` logs no slow-request
    /// warning and still answers.
    #[tokio::test(flavor = "current_thread")]
    async fn a_fast_method_through_handle_request_does_not_warn() {
        let tmp = tempfile::tempdir().expect("temp dir");
        let config = crate::config::NodeConfig {
            data_dir: tmp.path().to_path_buf(),
            ..crate::config::NodeConfig::default()
        };
        let node = Arc::new(TenzroNode::new(config).await.expect("node"));
        let request: JsonRpcRequest = serde_json::from_value(serde_json::json!({
            "jsonrpc": "2.0", "id": 1, "method": "tenzro_blockNumber", "params": []
        }))
        .expect("request");
        let (log, _guard) = crate::rpc_slow::test_capture::capture();
        let response = handle_request(&node, request, &AuthContext::default(), None).await;
        assert!(response.error.is_none(), "{:?}", response.error);
        assert!(!log.text().contains("slow RPC request"), "{}", log.text());
    }
}
